\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{tikz}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Custom Cool-Toned Color Theme ──
\definecolor{primary}{HTML}{0F172A}     % deep navy
\definecolor{secondary}{HTML}{0D9488}   % teal
\definecolor{accent}{HTML}{06B6D4}      % bright cyan
\definecolor{bgposter}{HTML}{F0F9FA}    % poster background (cool tint)
\definecolor{tealbg}{HTML}{F0FDFA}      % teal card background
\definecolor{cyanbg}{HTML}{ECFEFF}      % cyan card background
\definecolor{navybg}{HTML}{F1F5F9}      % navy card background
\definecolor{tealtitlebg}{HTML}{CCFBF1} % teal title bar background
\definecolor{cyantitlebg}{HTML}{CFFAFE} % cyan title bar background
\definecolor{navytitlebg}{HTML}{E2E8F0} % navy title bar background
\definecolor{textdark}{HTML}{1E293B}
\definecolor{textgray}{HTML}{475569}
\definecolor{statbg}{HTML}{E0F2FE}      % stat callout background

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyanbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cyantitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  navydarkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navybg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=navytitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

% ── Stat box macro ──
\newcommand{\statbox}[3]{%
  \fcolorbox{#1!30}{#1!12}{\parbox{0.88\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{52}{62}\selectfont\bfseries\color{#1} #2}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textgray} #3}\vspace{6pt}%
  }}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════
% TITLE BAR (rows 0-3)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{60}{72}\selectfont\bfseries GLOBAL INTERNET USAGE}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{accent!80} A Cross-Country Comparison of Digital Populations \& Penetration Rates}\\[10pt]
  {\fontsize{22}{28}\selectfont\color{white!55} Data Report 2025 \quad$\bullet$\quad
   Source: ITU \& Industry Estimates \quad$\bullet$\quad
   10 Leading Digital Economies}
}

% ═══════════════════════════════════════════════════════
% STATS BANNER (rows 4-5)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, halign=center,
  borderline south={3pt}{0pt}{primary!20},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \statbox{secondary}{5.56B}{Global Internet Users (2025)}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \statbox{accent}{68\%}{Global Penetration Rate}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \statbox{primary}{\$8.0T}{E-Commerce Sales (2027 est.)}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════
% ROW BAND A (rows 6-11): Digital Population + Penetration
% ═══════════════════════════════════════════════════════

% COL 1: The World's Digital Population
\posterbox[cyancard, title={THE WORLD'S DIGITAL POPULATION}
]{name=digitalpop, column=1, between=row6 and row11}{
  \fontsize{24}{32}\selectfont
  {\color{textgray} Top 10 countries by estimated online population (2025). Asia dominates with China and India representing over 35\% of the global digital population.}
  \vspace{4mm}

  % Horizontal bar chart for online populations
  \begin{tikzpicture}[xscale=1, yscale=0.92]
    \definecolor{barcyan}{HTML}{22D3EE}
    \definecolor{barteal}{HTML}{2DD4BF}
    \definecolor{barblue}{HTML}{60A5FA}
    \definecolor{barslate}{HTML}{94A3B8}
    % Max value ~1090 million for scaling
    \foreach \y/\country/\val/\color in {
      0/{China}{1090}{barcyan},
      1/{India}{900}{barcyan},
      2/{United States}{320}{barblue},
      3/{Indonesia}{220}{barteal},
      4/{Brazil}{190}{barteal},
      5/{Japan}{118}{barblue},
      6/{Nigeria}{115}{barteal},
      7/{Germany}{80}{barblue},
      8/{United Kingdom}{66}{barblue},
      9/{South Korea}{50}{barslate}
    }{
      \fill[\color!75] (0,-\y*0.95) rectangle ({min(11,\val/100)}, -\y*0.95+0.65);
      \fill[\color] (0,-\y*0.95) rectangle ({min(11,\val/90)}, -\y*0.95+0.65);
      \node[anchor=west, font=\fontsize{18}{22}\selectfont\bfseries, text=textdark] at (0.15,-\y*0.95+0.325) {\country};
      \node[anchor=east, font=\fontsize{18}{22}\selectfont\bfseries, text=textdark] at (10.85,-\y*0.95+0.325) {%
        \ifnum\val>900 \color{accent!80!black}\fi
        \ifnum\val<100 \color{textgray}\fi
        $\sim$\val\ M};
    }
  \end{tikzpicture}
  \vspace{2mm}
  {\fontsize{18}{22}\selectfont\color{textgray}\textit{Note: Bubble size proportional to online population.}}
}

% COL 2: Internet Penetration Rates (THE CENTERPIECE)
\posterbox[tealcard, title={INTERNET PENETRATION RATES}
]{name=penetration, column=2, between=row6 and row11}{
  \fontsize{24}{32}\selectfont
  {\color{textgray} Percentage of population with internet access. High-income countries near universal coverage; emerging economies show significant growth potential.}
  \vspace{3mm}

  \begin{tikzpicture}[xscale=1, yscale=0.92]
    \definecolor{highpen}{HTML}{0D9488}
