\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{tikz}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Custom Cool-Toned Color Theme ──
\definecolor{primary}{HTML}{0F172A}     % deep navy
\definecolor{secondary}{HTML}{0D9488}   % teal
\definecolor{accent}{HTML}{06B6D4}      % bright cyan
\definecolor{bgposter}{HTML}{F0F9FA}    % poster background (cool tint)
\definecolor{tealbg}{HTML}{F0FDFA}      % teal card background
\definecolor{cyanbg}{HTML}{ECFEFF}      % cyan card background
\definecolor{navybg}{HTML}{F1F5F9}      % navy card background
\definecolor{tealtitlebg}{HTML}{CCFBF1} % teal title bar background
\definecolor{cyantitlebg}{HTML}{CFFAFE} % cyan title bar background
\definecolor{navytitlebg}{HTML}{E2E8F0} % navy title bar background
\definecolor{textdark}{HTML}{1E293B}
\definecolor{textgray}{HTML}{475569}
\definecolor{statbg}{HTML}{E0F2FE}      % stat callout background

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyanbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cyantitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  navydarkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navybg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=navytitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

% ── Stat box macro ──
\newcommand{\statbox}[3]{%
  \fcolorbox{#1!30}{#1!12}{\parbox{0.88\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{52}{62}\selectfont\bfseries\color{#1} #2}\\[3pt]
    {\fontsize{20}{26}\selectfont\color{textgray} #3}\vspace{6pt}%
  }}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════
% TITLE BAR (rows 0-3)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{60}{72}\selectfont\bfseries GLOBAL INTERNET USAGE}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{accent!80} A Cross-Country Comparison of Digital Populations \& Penetration Rates}\\[10pt]
  {\fontsize{22}{28}\selectfont\color{white!55} Data Report 2025 \quad$\bullet$\quad
   Source: ITU \& Industry Estimates \quad$\bullet$\quad
   10 Leading Digital Economies}
}

% ═══════════════════════════════════════════════════════
% STATS BANNER (rows 4-5)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, halign=center,
  borderline south={3pt}{0pt}{primary!20},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \statbox{secondary}{5.56B}{Global Internet Users (2025)}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \statbox{accent}{68\%}{Global Penetration Rate}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \statbox{primary}{\$8.0T}{E-Commerce Sales (2027 est.)}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════
% ROW BAND A (rows 6-11): Digital Population + Penetration
% ═══════════════════════════════════════════════════════

% COL 1: The World's Digital Population
\posterbox[cyancard, title={THE WORLD'S DIGITAL POPULATION}
]{name=digitalpop, column=1, between=row6 and row11}{
  \fontsize{24}{32}\selectfont
  {\color{textgray} Top 10 countries by estimated online population (2025). Asia dominates with China and India representing over 35\% of the global digital population.}
  \vspace{4mm}

  % Horizontal bar chart for online populations
  \begin{tikzpicture}[xscale=1, yscale=0.92]
    \definecolor{barcyan}{HTML}{22D3EE}
    \definecolor{barteal}{HTML}{2DD4BF}
    \definecolor{barblue}{HTML}{60A5FA}
    \definecolor{barslate}{HTML}{94A3B8}
    % Max value ~1090 million for scaling
    \foreach \y/\country/\val/\color in {
      0/{China}{1090}{barcyan},
      1/{India}{900}{barcyan},
      2/{United States}{320}{barblue},
      3/{Indonesia}{220}{barteal},
      4/{Brazil}{190}{barteal},
      5/{Japan}{118}{barblue},
      6/{Nigeria}{115}{barteal},
      7/{Germany}{80}{barblue},
      8/{United Kingdom}{66}{barblue},
      9/{South Korea}{50}{barslate}
    }{
      \fill[\color!75] (0,-\y*0.95) rectangle ({min(11,\val/100)}, -\y*0.95+0.65);
      \fill[\color] (0,-\y*0.95) rectangle ({min(11,\val/90)}, -\y*0.95+0.65);
      \node[anchor=west, font=\fontsize{18}{22}\selectfont\bfseries, text=textdark] at (0.15,-\y*0.95+0.325) {\country};
      \node[anchor=east, font=\fontsize{18}{22}\selectfont\bfseries, text=textdark] at (10.85,-\y*0.95+0.325) {%
        \ifnum\val>900 \color{accent!80!black}\fi
        \ifnum\val<100 \color{textgray}\fi
        $\sim$\val\ M};
    }
  \end{tikzpicture}
  \vspace{2mm}
  {\fontsize{18}{22}\selectfont\color{textgray}\textit{Note: Bubble size proportional to online population.}}
}

% COL 2: Internet Penetration Rates (THE CENTERPIECE)
\posterbox[tealcard, title={INTERNET PENETRATION RATES}
]{name=penetration, column=2, between=row6 and row11}{
  \fontsize{24}{32}\selectfont
  {\color{textgray} Percentage of population with internet access. High-income countries near universal coverage; emerging economies show significant growth potential.}
  \vspace{3mm}

  \begin{tikzpicture}[xscale=1, yscale=0.92]
    \definecolor{highpen}{HTML}{0D9488}
    \definecolor{midhigh}{HTML}{14B8A6}
    \definecolor{midpen}{HTML}{2DD4BF}
    \definecolor{midlow}{HTML}{5EEAD4}
    \definecolor{lowpen}{HTML}{99F6E4}
    \foreach \y/\country/\pct/\color in {
      0/{South Korea}{98}{highpen},
      1/{United Kingdom}{97}{highpen},
      2/{Germany}{96}{highpen},
      3/{Japan}{95}{highpen},
      4/{United States}{95}{highpen},
      5/{Brazil}{88}{midhigh},
      6/{Indonesia}{78}{midpen},
      7/{China}{76}{midpen},
      8/{India}{62}{midlow},
      9/{Nigeria}{52}{lowpen}
    }{
      % Background bar extending to 100
      \fill[\color!15] (0,-\y*0.95) rectangle (10.5, -\y*0.95+0.65);
      % Filled portion
      \fill[\color!85] (0,-\y*0.95) rectangle ({\pct/100*10.5}, -\y*0.95+0.65);
      % Darker left edge for depth
      \fill[\color] (0,-\y*0.95) rectangle (0.15, -\y*0.95+0.65);
      \node[anchor=west, font=\fontsize{18}{22}\selectfont\bfseries, text=textdark] at (0.30,-\y*0.95+0.325) {\country};
      \node[anchor=east, font=\fontsize{20}{24}\selectfont\bfseries, text=textdark] at (10.35,-\y*0.95+0.325) {\pct\%};
    }
    % 50% and 100% markers
    \draw[textgray!40, thin] (5.25, -9.5) -- (5.25, 0.7);
    \node[font=\fontsize{14}{18}\selectfont, text=textgray!60] at (5.25, 0.95) {50\%};
    \node[font=\fontsize{14}{18}\selectfont, text=textgray!60] at (10.5, 0.95) {100\%};
  \end{tikzpicture}
  \vspace{1mm}
  {\fontsize{18}{22}\selectfont\color{textgray}\textit{Global average: 68\%. 4.4B people remain unconnected worldwide.}}
}

% ═══════════════════════════════════════════════════════
% ROW BAND B (rows 11-16): China+India Spotlight + Social Media
% ═══════════════════════════════════════════════════════

% COL 1: China & India Spotlight
\posterbox[highlightcard, title={CHINA \& INDIA: DIGITAL GIANTS}
]{name=china_india, column=1, between=row11 and row16}{
  \fontsize{26}{34}\selectfont
  \vspace{2mm}
  \begin{center}
  % China callout
  \colorbox{accent!15}{\parbox{0.90\linewidth}{
    \centering\vspace{8pt}
    {\fontsize{44}{52}\selectfont\bfseries\color{accent} 1.09 Billion}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textdark} China --- World's Largest Online Population}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textgray} 76\% Penetration \quad$\bullet$\quad 24\% of global users}\vspace{8pt}
  }}
  \vspace{5mm}
  % India callout
  \colorbox{secondary!15}{\parbox{0.90\linewidth}{
    \centering\vspace{8pt}
    {\fontsize{44}{52}\selectfont\bfseries\color{secondary} 900 Million}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textdark} India --- Fastest-Growing Digital Market}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textgray} 62\% Penetration \quad$\bullet$\quad 16\% of global users}\vspace{8pt}
  }}
  \end{center}
  \vspace{2mm}
  {\fontsize{20}{26}\selectfont\color{textdark}
  \begin{itemize}[itemsep=6pt]
    \item Together: \textbf{$\sim$2B users} --- over 35\% of the global digital population
    \item India adds \textbf{$\sim$50M new users/year}; China growth now from rural adoption
    \item Combined e-commerce markets exceed \textbf{\$3T annually}
  \end{itemize}}
}

% COL 2: Social Media & Daily Usage
\posterbox[navydarkcard, title={HOW THE WORLD SPENDS TIME ONLINE}
]{name=social, column=2, between=row11 and row16}{
  \fontsize{24}{32}\selectfont

  % Daily avg callout
  \begin{center}
  \colorbox{primary!12}{\parbox{0.90\linewidth}{
    \centering\vspace{6pt}
    {\fontsize{38}{46}\selectfont\bfseries\color{primary} 143 minutes}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textgray} Average daily social media usage per user (2025)}\vspace{6pt}
  }}
  \end{center}
  \vspace{3mm}

  {\fontsize{22}{28}\selectfont\bfseries\color{primary} Top Platforms by Monthly Active Users}
  \vspace{2mm}

  \renewcommand{\arraystretch}{1.5}
  {\fontsize{20}{26}\selectfont
  \begin{tabular}{p{0.55\linewidth}p{0.35\linewidth}}
    \textcolor{textgray}{Platform} & \textcolor{textgray}{MAU} \\
    \rowcolor{accent!10} Facebook    & $\sim$3.1 B \\
    \rowcolor{accent!5}  YouTube    & $\sim$2.5 B \\
    \rowcolor{accent!10} WhatsApp   & $\sim$2.4 B \\
    \rowcolor{accent!5}  Instagram  & $\sim$2.0 B \\
    \rowcolor{accent!10} TikTok     & $\sim$1.6 B \\
  \end{tabular}}
  \vspace{3mm}
  {\fontsize{18}{24}\selectfont\color{textgray}
  \begin{itemize}[itemsep=2pt]
    \item Latin America \& SE Asia lead in daily time spent
    \item Mobile traffic: \textbf{60\%+} of all web traffic worldwide
    \item Upward trend continues since 2012
  \end{itemize}}
}

% ═══════════════════════════════════════════════════════
% ROW BAND C (rows 16-20): Digital Economy + Takeaways
% ═══════════════════════════════════════════════════════

% COL 1: Digital Economy Impact
\posterbox[cyancard, title={THE DIGITAL ECONOMY IMPACT}
]{name=economy, column=1, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont

  \begin{center}
  \colorbox{accent!18}{\parbox{0.90\linewidth}{
    \centering\vspace{10pt}
    {\fontsize{48}{56}\selectfont\bfseries\color{primary} \$8.0 Trillion}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textdark} Global Retail E-Commerce Sales}\\[3pt]
    {\fontsize{19}{25}\selectfont\color{textgray} Projected by 2027 \quad$\bullet$\quad Up from \$6.3T in 2024}\vspace{10pt}
  }}
  \end{center}
  \vspace{4mm}

  {\fontsize{22}{28}\selectfont\bfseries\color{primary} Key Growth Indicators}
  \vspace{2mm}
  {\fontsize{20}{28}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{E-commerce share} of retail exceeds \textbf{20\%} globally
    \item \textbf{AI market:} \$240B (2023) $\to$ \textbf{\$800B+} (2030)
    \item \textbf{180+ zettabytes} of data created globally in 2025
  \end{itemize}}
  \vspace{2mm}
  {\fontsize{18}{24}\selectfont\color{textgray}\textit{Internet connectivity drives the world's fastest-growing economic sectors.}}
}

% COL 2: Key Takeaways
\posterbox[tealcard, title={KEY TAKEAWAYS}
]{name=takeaways, column=2, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont

  \begin{enumerate}[itemsep=10pt, leftmargin=22pt]
    \item \textbf{Asia dominates} in absolute online population; \textbf{Northern Europe \& East Asia} lead in penetration rates.
    \vspace{2mm}
    \item Social media engagement nears \textbf{2.5 hours/day} globally, with platform competition intensifying.
    \vspace{2mm}
    \item The digital economy is expanding rapidly --- \textbf{e-commerce \& AI} are primary growth engines.
    \vspace{2mm}
    \item \textbf{Connectivity gaps} remain in Sub-Saharan Africa and South Asia, representing both \textbf{challenges \& opportunities}.
  \end{enumerate}

  \vspace{3mm}
  \begin{center}
  \colorbox{secondary!15}{\parbox{0.88\linewidth}{
    \centering\vspace{6pt}
    {\fontsize{20}{26}\selectfont\bfseries\color{secondary} 4.4 billion people remain unconnected}\\[3pt]
    {\fontsize{18}{24}\selectfont\color{textdark} Closing the digital divide is the next frontier.}\vspace{6pt}
  }}
  \end{center}
  \vspace{2mm}

  % Subtle globe motif using TikZ circles
  \begin{center}
  \begin{tikzpicture}[scale=0.35]
    \draw[accent!30, thick] (0,0) circle (1.5);
    \draw[accent!25, thick] (0,-1.5) arc (-90:90:0.8 and 1.5);
    \draw[accent!25, thick] (0,-1.5) arc (-90:-270:0.5 and 1.5);
    \draw[accent!20, thin] (-1.5,0) -- (1.5,0);
    \draw[accent!20, thin] (-1.2,0.9) -- (1.2,0.9);
    \draw[accent!20, thin] (-1.2,-0.9) -- (1.2,-0.9);
    \fill[accent!50] (0,0) circle (0.12);
    \fill[accent!30] (0.6,-0.3) circle (0.08);
    \fill[accent!30] (-0.4,0.5) circle (0.07);
    \fill[accent!25] (0.8,0.6) circle (0.06);
    \fill[accent!25] (-0.7,-0.6) circle (0.07);
  \end{tikzpicture}
  \end{center}
  {\fontsize{16}{20}\selectfont\color{textgray!70}\centering Data: ITU, Datareportal, eMarketer (2025 estimates)}
}

\end{tcbposter}
